package com.hotelmanagement.hms.credit.model; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="credit_ledger") public class CreditLedgerEntry { @Id UUID id=UUID.randomUUID(); @Column(name="hotel_id") UUID hotelId; @Column(name="branch_id") UUID branchId; @Column(name="customer_id") UUID customerId; Instant entryDate; @Enumerated(EnumType.STRING) CreditEntryKind kind; BigDecimal amount; @Column(name="source_id") UUID sourceId; String description; @Column(name="actor_id") UUID actorId; protected CreditLedgerEntry(){} public static CreditLedgerEntry create(UUID h,UUID b,UUID c,CreditEntryKind k,BigDecimal a,UUID source,String d,UUID actor){var e=new CreditLedgerEntry();e.hotelId=h;e.branchId=b;e.customerId=c;e.kind=k;e.amount=a;e.sourceId=source;e.description=d;e.actorId=actor;e.entryDate=Instant.now();return e;} public BigDecimal getAmount(){return amount;} public CreditEntryKind getKind(){return kind;} }
